using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PhysicsSettingsOperations
{
    private static GDScript Module(string path)=>GD.Load<GDScript>("res://"+path+".gd");
    private static HashSet<string> ConstantSet(string path,string key){var result=new HashSet<string>();foreach(var value in Module(path).GetScriptConstantMap()[key].AsGodotArray())result.Add(value.AsString());return result;}
    public string fingerprint(RefCounted model)
    {
        var actors=model.Get("actors").AsGodotArray();var needed=new HashSet<string>();var queue=new Stack<string>();var geometryRoots=new HashSet<string>();var fog=Module("scripts/actors/fog/fog_motion_definition");var powder=Module("scripts/actors/physics/powder/powder_material");var damage=Module("scripts/actors/physics/destruction/destruction_material");var debrisVisual=ConstantSet("scripts/actors/physics/destruction/debris_definition","VISUAL");var damageVisual=ConstantSet("scripts/actors/physics/destruction/destruction_material","VISUAL");var fluidAppearance=ConstantSet("scripts/actors/physics/fluid/fluid_settings","APPEARANCE");var revisions=Module("Workspaces/EnvironmentWorkspace/environment_assets").Get("revisions").AsGodotDictionary();var omittedValues=new HashSet<string>{"structure_overlay","structure_assembly","destruction_overrides","destruction_setup","destruction_setup_actions","destruction_vfx_offset","growth_overrides"};var interiors=new HashSet<string>{"destruction_interior","destruction_interior_color","destruction_preset"};var visualValues=new HashSet<string>{"material","color","text_settings","image_path","shader","uniforms","text","physics"};
        foreach(var item in actors){var actor=item.As<Resource>();bool enabled=configured(actor);if(enabled)queue.Push(actor.Get("id").AsString());if(enabled&&Type(actor)=="powder")geometryRoots.Add(Get(Values(actor),"powder_mesh_actor","").AsString());}
        void Characters(){foreach(var item in actors){var candidate=item.As<Resource>();if(Get(Values(candidate),"rig_bones",new GArray()).AsGodotArray().Count>0)queue.Push(candidate.Get("id").AsString());}}
        while(queue.Count>0){string id=queue.Pop();if(needed.Contains(id))continue;var actor=model.Call("actor_for_id",id).As<Resource>();if(actor==null)continue;needed.Add(id);var values=Values(actor);string type=Type(actor);if(type=="fog_volume"){foreach(var dependency in fog.Call("dependencies",actor).AsGodotArray())queue.Push(dependency.AsString());if(Get(values,"fog_character_proxies",true).AsBool())Characters();}string skeleton=Get(values,"model_skeleton_actor","").AsString();if(skeleton.Length>0)queue.Push(skeleton);foreach(string category in new[]{"powder","fluid"})if(type==category){queue.Push(Get(values,category+"_mesh_actor","").AsString());if(Get(values,category+"_characters",true).AsBool())Characters();}foreach(var item in actors){var driver=item.As<Resource>();if(Type(driver)=="remote_transform"&&Get(Values(driver),"remote_actor","").AsString()==id)queue.Push(driver.Get("id").AsString());}string parentId=actor.Get("parent_id").AsString();if(parentId.Length>0)queue.Push(parentId);var settings=authored(actor);foreach(string key in new[]{"attachment","end_actor"})if(settings[key].AsString().Length>0)queue.Push(settings[key].AsString());foreach(var item in settings["pins"].AsGodotArray()){string target=Get(item.AsGodotDictionary(),"actor","").AsString();if(target.Length>0)queue.Push(target);}if(configured(actor)||geometryRoots.Contains(id))foreach(var item in actors){var candidate=item.As<Resource>();var parent=model.Call("actor_for_id",candidate.Get("parent_id")).As<Resource>();var seen=new HashSet<string>();while(parent!=null&&seen.Add(parent.Get("id").AsString())){if(parent.Get("id").AsString()==id){queue.Push(candidate.Get("id").AsString());break;}parent=model.Call("actor_for_id",parent.Get("parent_id")).As<Resource>();}}}
        var data=new GArray();foreach(var item in actors)
        {
            var actor=item.As<Resource>();if(!needed.Contains(actor.Get("id").AsString()))continue;string type=Type(actor);var source=Values(actor);var values=new Settings();var clip=model.Call("clip_for_actor_id",actor.Get("id")).As<Resource>();if(type is "basic_shape" or "basic_mesh"){var material=damage.Call("resolve",source).As<Resource>();if(material!=null)values["resolved_damage_material"]=damage.Call("physical",material);}
            foreach(var entry in source){string key=entry.Key.AsString();if(type=="fog_volume"){if(fog.Call("physical_path",new[]{key}).AsBool())values[key]=canonical(fog.Call("content",entry.Value));continue;}if(key=="shadow_casting"||key.StartsWith("growth_",StringComparison.Ordinal)||omittedValues.Contains(key)||debrisVisual.Contains(key)||interiors.Contains(key))continue;if(key is "destruction_material" or "destruction_region" or "destruction_region_2"){values[key]=damage.Call("physical",entry.Value);continue;}if(type=="fluid"&&fluidAppearance.Contains(key)||type=="powder"&&!powder.Call("physical_path",new[]{key}).AsBool()||visualValues.Contains(key))continue;values[key]=canonical(entry.Value);if(entry.Value.VariantType==Variant.Type.String&&Godot.FileAccess.FileExists(entry.Value.AsString())){if(key=="mesh_path")values["mesh_modified"]=Godot.FileAccess.GetModifiedTime(entry.Value.AsString());if(key=="environment_path")values["environment_modified"]=new GArray{Godot.FileAccess.GetModifiedTime(entry.Value.AsString()),Get(revisions,entry.Value.AsString(),0)};}}
            var config=authored(actor);if(config["mode"].AsInt32()==4)config["mode"]=Get(config["bake"].AsGodotDictionary(),"source_mode",1).AsInt32();config.Remove("bake");var tracks=new GArray();foreach(var trackValue in actor.Get("animation_tracks").AsGodotArray()){var track=trackValue.As<Resource>();var path=track.Get("path").AsStringArray();if(type=="fog_volume"&&!fog.Call("physical_path",path).AsBool())continue;if(path.Length>0&&(path[0]=="shadow_casting"||path[0].StartsWith("growth_",StringComparison.Ordinal)||path[0] is "destruction_overrides" or "destruction_vfx_offset"||debrisVisual.Contains(path[0])||interiors.Contains(path[0])))continue;if(path.Length>1&&path[0]=="destruction_material"&&damageVisual.Contains(path[1]))continue;if(type=="fluid"&&path.Length>0&&fluidAppearance.Contains(path[0])||type=="powder"&&!powder.Call("physical_path",path).AsBool())continue;if(path.Length==0||new[]{"material","color","text_settings","image_path","shader","uniforms","text"}.Contains(path[0]))continue;var keys=new GArray();foreach(var keyValue in track.Get("keys").AsGodotArray()){var key=keyValue.As<Resource>();keys.Add(new GArray{key.Get("time"),canonical(key.Get("value")),key.Get("interpolation"),key.Get("attenuation"),canonical(key.Get("value_curve"))});}tracks.Add(new GArray{path,keys});}
            var previews=new Settings();foreach(var previewEntry in actor.Get("animation_previews").AsGodotDictionary()){var preview=previewEntry.Value.AsGodotDictionary();var path=preview["path"].AsStringArray();if(type=="fog_volume"){if(fog.Call("physical_path",path).AsBool())previews[previewEntry.Key]=preview;continue;}if(path.Length==0)continue;string key=path[0];if(key is "destruction_overrides" or "destruction_vfx_offset"||key.StartsWith("growth_",StringComparison.Ordinal))continue;if(key.StartsWith("destruction_",StringComparison.Ordinal)&&!interiors.Contains(key)&&(path.Length<2||!damageVisual.Contains(path[1])))previews[previewEntry.Key]=preview;if(new[]{"physics","position","rotation","scale","bone_poses"}.Contains(key)||type=="fluid"&&!fluidAppearance.Contains(key)||type=="powder"&&powder.Call("physical_path",path).AsBool())previews[previewEntry.Key]=preview;if(key.StartsWith("structure_",StringComparison.Ordinal)&&key is not ("structure_overlay" or "structure_assembly"))previews[previewEntry.Key]=preview;}
            data.Add(new GArray{actor.Get("id"),actor.Get("type_id"),actor.Get("parent_id"),values,config,tracks,canonical(previews),clip!=null?new GArray{clip.Get("start_time"),clip.Get("duration"),clip.Get("source_offset"),clip.Get("playback_speed")}:new GArray()});
        }
        return GD.VarToStr(canonical(data)).Sha256Text();
    }
}
